#include "c_gradbench_quadrouting_d.h"

/* Functions copied from quasaore_core to simplify application of Tapenade */
int gb_notnull_c(double x) {
    return (x < 0 || x > 0 ? 1 : 0);
}

int gb_isnull_c(double x) {
    int result1;
    result1 = gb_notnull_c(x);
    return 1 - result1;
}

/*
  Differentiation of gb_omega_fun in forward (tangent) mode:
   variations   of useful results: gb_omega_fun
   with respect to varying inputs: x
*/
double gb_omega_fun_d(double x, double xd, double Delta, double *gb_omega_fun)
{
    if (Delta < 0.) {
        *gb_omega_fun = tan(x);
        return (1.0+tan(x)*tan(x))*xd;
    } else {
        *gb_omega_fun = tanh(x);
        return (1.0-tanh(x)*tanh(x))*xd;
    }
}

/*
  Differentiation of gb_constants in forward (tangent) mode:
   variations   of useful results: constants[0:4-1]
   with respect to varying inputs: c
   Plus diff mem management of: constants:in
*/
int gb_constants_d(double a, double b, double c, double cd, double constants[4
        ], double constantsd[4]) {
    /* Delta (not very robust numerically, see c_quasoare_core for
     * a better formulation */
    double Delta = b*b - 4*a*c;
    double Deltad = -(a*4*cd);
    double fabs0;
    double fabs0d;
    double result1;
    double result1d;
    int ii1;
    double temp;
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    constantsd[0] = Deltad;
    constants[0] = Delta;
    /* signD */
    constantsd[1] = 0.0;
    constants[1] = (Delta < 0 ? -1. : 1.);
    if (Delta >= 0.0) {
        fabs0d = Deltad;
        fabs0 = Delta;
    } else {
        fabs0d = -Deltad;
        fabs0 = -Delta;
    }
    /* qD */
    temp = sqrt(fabs0);
    result1d = (fabs0 == 0.0 ? 0.0 : fabs0d/(2.0*temp));
    result1 = temp;
    constantsd[2] = result1d/2;
    constants[2] = result1/2;
    /* sbar */
    constantsd[3] = 0.0;
    constants[3] = -b/2./a;
    return 0;
}

/*
  Differentiation of gb_forward in forward (tangent) mode:
   variations   of useful results: gb_forward
   with respect to varying inputs: s0 constants[0:4-1] c
   Plus diff mem management of: constants:in
*/
double gb_forward_d(double a, double b, double c, double cd, double constants[
        4], double constantsd[4], double timestep, double s0, double s0d, 
        double *gb_forward) {
    double s1 = 0;
    double s1d;
    double omega = 0.;
    double omegad;
    double exparg = 0;
    double tau = timestep;
    double Delta = constants[0];
    double signD = constants[1];
    double signDd = constantsd[1];
    double qD = constants[2];
    double qDd = constantsd[2];
    double sbar = constants[3];
    double sbard = constantsd[3];
    double fabs0;
    int result1;
    int result2;
    double temp;
    double temp0;
    double temp1;
    result1 = gb_isnull_c(a);
    result2 = gb_isnull_c(b);
    if (result1 && result2) {
        s1d = s0d + tau*cd;
        s1 = s0 + c*tau;
    } else {
        result1 = gb_isnull_c(a);
        result2 = gb_notnull_c(b);
        if (result1 && result2) {
            exparg = b*tau;
            if (exparg >= 0.0)
                fabs0 = exparg;
            else
                fabs0 = -exparg;
            temp = exp(exparg);
            s1d = (fabs0 < 1e-12 ? (exparg+1)*s0d + tau*cd : temp*(s0d+cd/b) -
                cd/b);
            s1 = (fabs0 < 1e-12 ? (exparg+1)*s0 + tau*c : temp*(s0+c/b) - c/b)
            ;
        } else {
            result1 = gb_isnull_c(Delta);
            if (result1) {
                temp = -(a*tau*(s0-sbar)) + 1;
                temp0 = (s0-sbar)/temp;
                s1d = sbard + (s0d-sbard+temp0*a*tau*(s0d-sbard))/temp;
                s1 = sbar + temp0;
            } else {
                omegad = gb_omega_fun_d(qD*tau, tau*qDd, Delta, &omega);
                temp0 = omega/qD;
                temp = -(a*(s0-sbar)*temp0) + 1.;
                temp1 = (s0-sbar-signD*qD*omega/a)/temp;
                s1d = sbard + (s0d-sbard-omega*(qD*signDd+signD*qDd)/a-signD*
                    qD*omegad/a+temp1*a*(temp0*(s0d-sbard)+(s0-sbar)*(omegad-
                    temp0*qDd)/qD))/temp;
                s1 = sbar + temp1;
            }
        }
    }
    *gb_forward = s1;
    return s1d;
}

/*
  Differentiation of ro_route_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: gamma *flux qstar1 x0 *state
   Plus diff mem management of: flux:in state:in
*/
int ro_route_runtimestep_d(double qstar1, double qstar1d, double timestep, 
        double gamma, double gammad, double x0, double x0d, double *state, 
        double *stated, double *flux, double *fluxd) {
    /* Quasaore coefficients
     * dx/dt = Q1* / ? - 1/? x^2
     *       = a x^2 + b x + c
     *
     * Output flux = Q1* - Q1 - Q2
     * F = Q1* - Q1* (1 - intx2) + ?/?  4^3/9^4 intx2
     */
    double a = -1./timestep;
    double b = 0;
    double c = qstar1/gamma;
    double cd = (qstar1d-qstar1*gammad/gamma)/gamma;
    double constants[4];
    double constantsd[4];
    int ii1;
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    gb_constants_d(a, b, c, cd, constants, constantsd);
    /* Applies Quasaore solution */
    double x1;
    double x1d;
    x1d = gb_forward_d(a, b, c, cd, constants, constantsd, timestep, x0, x0d, 
                       &x1);
    *stated = x1d;
    *state = x1;
    *fluxd = qstar1d - gamma*(x1d-x0d)/timestep - (x1-x0)*gammad/timestep;
    *flux = qstar1 - gamma/timestep*(x1-x0);
    return 0;
}

/*
  Differentiation of c_gradbench_quadrouting in forward (tangent) mode:
   variations   of useful results: *qout_ro_route
   with respect to varying inputs: *gammas_ro_route
   RW status of diff variables: gammas_ro_route:(loc) *gammas_ro_route:in
                qout_ro_route:(loc) *qout_ro_route:out
   Plus diff mem management of: gammas_ro_route:in states_ro_route:in
                qout_ro_route:in
*/
int c_gradbench_quadrouting_d(int nval, int nreaches, double timestep, double 
        *x0_ro_route, double *gammas_ro_route, double *gammas_ro_routed, 
        double *qin, double *states_ro_route, double *states_ro_routed, double
        *qout_ro_route, double *qout_ro_routed) {
    int i, j, k;
    double qi;
    double qid;
    double xini;
    double xinid;
    double gam;
    double gamd;
    *states_ro_routed = 0.0;
    *qout_ro_routed = 0.0;
    /* Loop through reaches */
    for (i = 0; i < nreaches; ++i) {
        /* initialise reach model */
        xini = x0_ro_route[i];
        gamd = gammas_ro_routed[i];
        gam = gammas_ro_route[i];
        xinid = 0.0;
        /* Time series loop */
        for (j = 0; j < nval; ++j) {
            /* Get inflow */
            k = j*nreaches + i - 1;
            qid = (i == 0 ? 0.0 : qout_ro_routed[k]);
            qi = (i == 0 ? qin[j] : qout_ro_route[k]);
            /* Run model */
            k = j*nreaches + i;
            ro_route_runtimestep_d(qi, qid, timestep, gam, gamd, xini, xinid, 
                                   &(states_ro_route[k]), &(states_ro_routed[k
                                   ]), &(qout_ro_route[k]), &(qout_ro_routed[k
                                   ]));
            /* Set timestep for next iteration */
            xinid = states_ro_routed[k];
            xini = states_ro_route[k];
        }
    }
    return 0;
}
